mapper.select:
/*mycat:sql=select id from ap_collection where burst='${burst}'*/
  select  from ap_collection
  where behavior_entry_id = #{objectId} and type = #{type}
  order by collection_time desc limit #{offset}, #{size}

mapper.delete:
/*mycat:sql=delete from ap_collection where burst='${burst}'*/
  delete from ap_collection
  where behavior_entry_id = #{objectId} and entry_id = #{entryId} and type = #{type}
